// @ts-expect-error - parâmetro sem tipo e sem valor por omissão: o TypeScript
// não tem como inferir nada, noImplicitAny torna isto um erro em vez de any
function dobro(x) {
  return x * 2;
}

function dobroTipado(x: number): number {
  return x * 2;
}
console.log(dobroTipado(4)); // 8

// @ts-expect-error - null só é atribuível a string quando strictNullChecks está desligado
let nome: string = null;

// com strictNullChecks, um valor que pode faltar tem de o dizer explicitamente no tipo
function tamanho(texto: string | null): number {
  if (texto === null) {
    return 0;
  }
  return texto.length;
}
console.log(tamanho("ola")); // 3
console.log(tamanho(null)); // 0

class Animal {
  nome: string = "animal";
}
class Cao extends Animal {
  raca: string = "vira-lata";
}

// propriedade cujo valor é um tipo de função: comparada por contravariância
interface ComPropriedade {
  processar: (a: Animal) => void;
}

// mesma forma, mas escrita com sintaxe de método: comparada por bivariância,
// uma exceção histórica mantida por compatibilidade com padrões antigos
interface ComMetodo {
  processar(a: Animal): void;
}

const processaCao = (c: Cao): void => {
  console.log(c.raca);
};

const viaPropriedade: ComPropriedade = {
  // @ts-expect-error - contravariante: uma função que só aceita Cao não pode
  // substituir uma que promete aceitar qualquer Animal
  processar: processaCao,
};

const viaMetodo: ComMetodo = {
  // sintaxe de método: bivariante, o compilador aceita mesmo sendo inseguro
  processar: processaCao,
};

// a insegurança fica visível em runtime: chamar com um Animal que não é Cao
// não lança erro nenhum, só acede a uma propriedade que não existe
viaMetodo.processar(new Animal()); // undefined

function saudar(nome: string, vezes: number): string {
  return `${nome}, `.repeat(vezes);
}

console.log(saudar.call(null, "Ana", 2)); // Ana, Ana,

// @ts-expect-error - o segundo argumento tem de ser number, não string
saudar.call(null, "Ana", "duas");

const saudarBruno = saudar.bind(null, "Bruno");
console.log(saudarBruno(3)); // Bruno, Bruno, Bruno,

// @ts-expect-error - bind também verifica os argumentos parciais contra a assinatura real
saudar.bind(null, 123);

console.log(saudar.apply(null, ["Carla", 1])); // Carla,

// @ts-expect-error - apply verifica que o array de argumentos bate certo com os parâmetros
saudar.apply(null, ["Carla", "um"]);

class Encomenda {
  // @ts-expect-error - campo declarado mas nunca inicializado, nem no campo nem no construtor
  referencia: string;

  // válido: inicializado na própria declaração
  estado: string = "pendente";

  // válido: inicializado no construtor
  total: number;

  // válido: definite assignment assertion (!) promete que será inicializado antes de usar
  transportadora!: string;

  // válido: opcional, undefined faz parte do tipo
  notas?: string;

  constructor(total: number) {
    this.total = total;
  }
}

const e = new Encomenda(50);
console.log(e.estado, e.total); // pendente 50

// classe equivalente com parameter properties (Módulo 08): o campo é inicializado
// na própria assinatura do construtor, por isso nunca há erro de inicialização
class EncomendaComParameterProperty {
  constructor(
    public total: number,
    public estado: string = "pendente"
  ) {}
}

const e2 = new EncomendaComParameterProperty(75);
console.log(e2.estado, e2.total); // pendente 75

function obterValor() {
  // @ts-expect-error - this não tem um tipo que o compilador consiga inferir aqui
  return this.valor;
}

// com o parâmetro this explícito como primeiro parâmetro (nunca passado na chamada),
// o compilador passa a verificar o acesso
function obterValorTipado(this: { valor: number }) {
  return this.valor;
}

const contador = { valor: 10, obterValorTipado };
console.log(contador.obterValorTipado()); // 10

// alwaysStrict garante que o código corre sempre em modo estrito do próprio
// JavaScript: escrever numa propriedade congelada lança TypeError em vez de
// falhar em silêncio. Como este bloco (como qualquer ficheiro com import ou
// export) já é um módulo ES, e módulos são sempre estritos por especificação,
// o efeito prático aqui está garantido de qualquer forma - alwaysStrict
// importa sobretudo em scripts sem import/export nenhum.
interface Config {
  modo: string;
}
const config: Config = Object.freeze({ modo: "producao" });
try {
  (config as { modo: string }).modo = "debug";
} catch (erro) {
  console.log("erro:", (erro as Error).message);
}
console.log(config.modo); // producao

// useUnknownInCatchVariables (desde o TypeScript 4.4): a variável do catch
// tem tipo unknown, não any - obriga a confirmar o tipo antes de a usar
function processar(valor: number): number {
  if (valor < 0) {
    throw new Error("valor negativo");
  }
  return valor * 2;
}

try {
  processar(-1);
} catch (erroProcessamento) {
  // @ts-expect-error - erroProcessamento é unknown, .message não existe em unknown
  console.log(erroProcessamento.message);
}

try {
  processar(-1);
} catch (erroProcessamento) {
  // o padrão já usado em todo o curso desde aqui: asserção de tipo
  console.log((erroProcessamento as Error).message); // valor negativo
}

