function somarPrecos(precos: number[]): number {
  return precos.reduce((total, preco) => total + preco, 0);
}

console.log(somarPrecos([10, 20, 30])); // 60

class Utilizador {
  id: number;
  nome: string = "anónimo";
  sessaoAtual!: string;
  apelido?: string;

  constructor(id: number) {
    this.id = id;
  }

  iniciarSessao(token: string): void {
    this.sessaoAtual = token;
  }
}

const u = new Utilizador(1);
u.iniciarSessao("abc123");
console.log(u.id, u.nome, u.sessaoAtual); // 1 anónimo abc123

class Forma {
  tipo: string = "forma";
}
class Circulo extends Forma {
  raio: number = 1;
}

interface ProcessadorPropriedade {
  processar: (f: Forma) => void;
}
interface ProcessadorMetodo {
  processar(f: Forma): void;
}

const processaCirculo = (c: Circulo): void => {
  console.log(c.raio);
};

const p1: ProcessadorPropriedade = {
  // @ts-expect-error - contravariante: só aceita Circulo, não serve para qualquer Forma
  processar: processaCirculo,
};

const p2: ProcessadorMetodo = {
  // sintaxe de método: exceção bivariante, o compilador aceita
  processar: processaCirculo,
};

console.log(typeof p2.processar); // function

function validarIdade(idade: number): void {
  if (idade < 0) {
    throw new Error("idade não pode ser negativa");
  }
  console.log(`idade válida: ${idade}`);
}

try {
  validarIdade.call(null, -5);
} catch (erro) {
  if (erro instanceof Error) {
    console.log("erro:", erro.message); // erro: idade não pode ser negativa
  }
}

// @ts-expect-error - call verifica o tipo do argumento contra a assinatura real
validarIdade.call(null, "vinte");
